import{_ as o,c as l,a2 as a,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千一百九十四章 断除五盖品 增支部1集11经到20经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1194第一千一百九十四章 断除五盖品 增支部1集11经到20经.md","filePath":"meditation/巴利文大藏经/1194第一千一百九十四章 断除五盖品 增支部1集11经到20经.md"}'),p={name:"meditation/巴利文大藏经/1194第一千一百九十四章 断除五盖品 增支部1集11经到20经.md"};function e(r,t,_,s,u,n){return i(),l("div",null,t[0]||(t[0]=[a('<h1 id="第一千一百九十四章-断除五盖品-增支部1集11经到20经" tabindex="-1">第一千一百九十四章 断除五盖品 增支部1集11经到20经 <a class="header-anchor" href="#第一千一百九十四章-断除五盖品-增支部1集11经到20经" aria-label="Permalink to &quot;第一千一百九十四章 断除五盖品 增支部1集11经到20经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集11经到20经</p><p>断除五盖品</p><p>11经</p><ol start="11"><li>&quot;比丘们,我不见有任何一法,能使未生起的欲贪生起,或使已生起的欲贪增长广大,如同这个,比丘们,即净相。比丘们,对净相不如理作意者,未生起的欲贪便会生起,已生起的欲贪便会增长广大。&quot;</li></ol><p>12经</p><ol start="12"><li>&quot;比丘们,我不见有任何一法,能使未生起的嗔恚生起,或使已生起的嗔恚增长广大,如同这个,比丘们,即瞋相。比丘们,对瞋相不如理作意者,未生起的嗔恚便会生起,已生起的嗔恚便会增长广大。&quot;</li></ol><p>13经</p><ol start="13"><li>&quot;比丘们,我不见有任何一法,能使未生起的昏沉睡眠生起,或使已生起的昏沉睡眠增长广大,如同这个,比丘们,即不乐、懈怠、伸懒腰、饮食后昏沉、心的退缩。比丘们,心退缩者,未生起的昏沉睡眠便会生起,已生起的昏沉睡眠便会增长广大。&quot;</li></ol><p>14经</p><ol start="14"><li>&quot;比丘们,我不见有任何一法,能使未生起的掉举恶作生起,或使已生起的掉举恶作增长广大,如同这个,比丘们,即心的不寂静。比丘们,心不寂静者,未生起的掉举恶作便会生起,已生起的掉举恶作便会增长广大。&quot;</li></ol><p>15经</p><ol start="15"><li>&quot;比丘们,我不见有任何一法,能使未生起的疑惑生起,或使已生起的疑惑增长广大,如同这个,比丘们,即不如理作意。比丘们,不如理作意者,未生起的疑惑便会生起,已生起的疑惑便会增长广大。&quot;</li></ol><p>16经</p><ol start="16"><li>&quot;比丘们,我不见有任何一法,能使未生起的欲贪不生起,或使已生起的欲贪断除,如同这个,比丘们,即不净相。比丘们,如理作意不净相者,未生起的欲贪便不会生起,已生起的欲贪便会断除。&quot;</li></ol><p>17经</p><ol start="17"><li>&quot;比丘们,我不见有任何一法,能使未生起的嗔恚不生起,或使已生起的嗔恚断除,如同这个,比丘们,即慈心解脱。比丘们,如理作意慈心解脱者,未生起的嗔恚便不会生起,已生起的嗔恚便会断除。&quot;</li></ol><p>18经</p><ol start="18"><li>&quot;比丘们,我不见有任何一法,能使未生起的昏沉睡眠不生起,或使已生起的昏沉睡眠断除,如同这个,比丘们,即发勤精进、奋发、勇猛。比丘们,精进努力者,未生起的昏沉睡眠便不会生起,已生起的昏沉睡眠便会断除。&quot;</li></ol><p>19经</p><ol start="19"><li>&quot;比丘们,我不见有任何一法,能使未生起的掉举恶作不生起,或使已生起的掉举恶作断除,如同这个,比丘们,即心的寂静。比丘们,心寂静者,未生起的掉举恶作便不会生起,已生起的掉举恶作便会断除。&quot;</li></ol><p>20经</p><ol start="20"><li>&quot;比丘们,我不见有任何一法,能使未生起的疑惑不生起,或使已生起的疑惑断除,如同这个,比丘们,即如理作意。比丘们,如理作意者,未生起的疑惑便不会生起,已生起的疑惑便会断除。&quot;</li></ol><p>断除五盖品第二终。</p>',25)]))}const c=o(p,[["render",e]]);export{d as __pageData,c as default};
